-- Schema specification, version 0.1.0; not an automatic importer.
-- Create each database in a clean customer root and replace RELATION targets
-- with the actual returned data-source IDs. Never link private operator tables.
CREATE TABLE "Artists" ("Name" TITLE, "Stable ID" RICH_TEXT, "Listener promise" RICH_TEXT, "Sonic boundary" RICH_TEXT, "Identity kind" SELECT('Human':blue,'Virtual':purple,'Collective':pink), "Name status" SELECT('Open':orange,'Reviewed':blue,'Cleared evidence':green), "Next action" RICH_TEXT);
CREATE TABLE "Albums & Campaigns" ("Name" TITLE, "Stable ID" RICH_TEXT, "Artist" RELATION('ARTISTS_DS'), "Stage" SELECT('Brief':gray,'Producing':blue,'Selecting':purple,'Staging':yellow,'Delivered evidence':green,'Learning':pink,'Held':red), "Production path" SELECT('Human':blue,'Hybrid':purple,'Generated':pink), "Primary strategy" SELECT('Single ladder':blue,'World album':purple,'Performance catalog':green,'Scene test':orange,'Sync library':gray), "Thesis" RICH_TEXT, "Budget cap EUR" NUMBER FORMAT 'euro', "Next action" RICH_TEXT, "Target date" DATE);
CREATE TABLE "Recordings" ("Name" TITLE, "Stable ID" RICH_TEXT, "Campaign" RELATION('CAMPAIGNS_DS'), "Revision" RICH_TEXT, "Asset SHA256" RICH_TEXT, "Private export pointer" RICH_TEXT, "Creative" SELECT('Prepared':gray,'Rendered':blue,'Heard':purple,'Selected':green,'Revise':orange), "Rights" SELECT('Unknown':gray,'In review':orange,'Evidence reviewed':green), "Delivery" SELECT('Not submitted':gray,'Pending':blue,'Receipt recorded':purple,'Live verified':green,'Uncertain':red), "Exact review" RICH_TEXT, "Next blocker" RICH_TEXT);
CREATE TABLE "Knowledge & Experiments" ("Name" TITLE, "Stable ID" RICH_TEXT, "Campaign" RELATION('CAMPAIGNS_DS'), "Type" SELECT('Source fact':blue,'Craft inference':purple,'Hypothesis':yellow,'Listening observation':pink,'Campaign observation':green,'Learned rule':orange), "State" SELECT('Proposed':gray,'Researched':blue,'Running evidence':purple,'Observed':green,'Superseded':orange), "Source" URL, "Claim or hypothesis" RICH_TEXT, "Scope and denominator" RICH_TEXT, "Decision rule" RICH_TEXT, "Observation" RICH_TEXT, "Next use" RICH_TEXT, "Checked" DATE);
CREATE TABLE "Cost Ledger" ("Name" TITLE, "Stable ID" RICH_TEXT, "Campaign" RELATION('CAMPAIGNS_DS'), "Category" SELECT('Subscriptions':gray,'Production':blue,'Visuals':pink,'Distribution':purple,'Marketing':orange,'Reasoning':yellow,'Reserve':green), "Allowance EUR" NUMBER FORMAT 'euro', "Actual EUR" NUMBER FORMAT 'euro', "State" SELECT('Planned':gray,'Quoted':blue,'Authorized':purple,'Reconciled':green,'Uncertain':red), "Receipt" RICH_TEXT, "Original currency and conversion" RICH_TEXT);
CREATE TABLE "Actions" ("Name" TITLE, "Stable ID" RICH_TEXT, "Campaign" RELATION('CAMPAIGNS_DS'), "Stage" RICH_TEXT, "Status" SELECT('Next':blue,'Waiting':orange,'Done evidence':green,'Held':red), "Evidence needed" RICH_TEXT, "Agent responsibility" RICH_TEXT, "Permission boundary" RICH_TEXT, "Due" DATE);

